-- ── 0085. THE CHANNELS, AS DATA ────────────────────────────────────────────────────────────────
-- scripts/sea-grid.mjs CHANNELS is the ONE authority for "you may pass here"; this table is that
-- list crossing the wire so the SQL roadstead rule can read it — never a second place to edit a
-- channel. Two things ride with each polyline that SQL could not re-derive: the cells of DRY
-- LAND the carve opened (the land polygons are not in the database), and opens_land, the count
-- the authored list declares, CHECKed equal to that list's length so a stale seed cannot apply.
-- Server-only: RLS on, no policy, no client grant — a player is served the roadstead, not the
-- machinery that decided it.
create table if not exists voyage.channels (
  id           text primary key,
  name         text  not null,
  points       jsonb not null,
  carved_cells jsonb not null,
  opens_land   int   not null,
  constraint channels_points_are_a_line
    check (jsonb_typeof(points) = 'array' and jsonb_array_length(points) >= 2),
  constraint channels_carve_is_counted
    check (jsonb_typeof(carved_cells) = 'array' and jsonb_array_length(carved_cells) = opens_land)
);
comment on table voyage.channels is
  'THE CHANNELS (0085): scripts/sea-grid.mjs CHANNELS as data, one row per authored strait or '
  'river, replaced whole by every sea migration. points is the polyline [[lat, lon], ...] in '
  'order along ONE water; carved_cells lists the public.sea_raster cell indices (row * cols + col) '
  'of DRY LAND this carve turned into sea, measured against the scan-filled land data; opens_land '
  'is the count the authored list declares. voyage.water_roadstead reads carved_cells to decide '
  'that a roadstead lies on the channel rather than at a cell centre the land data calls land.';
alter table voyage.channels enable row level security;
revoke all on voyage.channels from public, anon, authenticated;
delete from voyage.channels;
