-- ── 0085. THE FOOT: the point on one channel nearest a point ───────────────────────────────────
-- The generator's channelFoot, operation for operation: planar per segment with longitude scaled
-- by cos(lat) of the QUERY point, clamped to the segment, rounded to 3 dp, measured back by the
-- one distance authority, first segment wins a tie. Same float64 arithmetic in the same order,
-- which is what lets self-assert (e) demand the seeded point EQUAL this answer on every row.
create or replace function voyage.channel_foot(p_channel text, p_lat numeric, p_lon numeric)
returns table (lat numeric, lon numeric, nm numeric)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $cf$
declare
  v_pts  jsonb;
  v_n    int;
  i      int;
  v_k    float8; v_alat float8; v_alon float8; v_blat float8; v_blon float8;
  v_ax   float8; v_ay float8; v_bx float8; v_by float8; v_dx float8; v_dy float8;
  v_len2 float8; v_t float8; v_d float8;
  v_flat numeric; v_flon numeric;
  v_best float8 := null; v_best_lat numeric; v_best_lon numeric;
begin
  select c.points into v_pts from voyage.channels c where c.id = p_channel;
  if v_pts is null then
    raise exception 'voyage.channel_foot: no channel named %', p_channel;
  end if;
  v_n := jsonb_array_length(v_pts);
  v_k := cos(radians(p_lat::float8));
  for i in 1 .. v_n - 1 loop
    v_alat := (v_pts->(i - 1)->>0)::float8; v_alon := (v_pts->(i - 1)->>1)::float8;
    v_blat := (v_pts->i->>0)::float8;       v_blon := (v_pts->i->>1)::float8;
    v_ax := (v_alon - p_lon::float8) * v_k; v_ay := v_alat - p_lat::float8;
    v_bx := (v_blon - p_lon::float8) * v_k; v_by := v_blat - p_lat::float8;
    v_dx := v_bx - v_ax; v_dy := v_by - v_ay;
    v_len2 := v_dx * v_dx + v_dy * v_dy;
    v_t := case when v_len2 = 0 then 0 else -(v_ax * v_dx + v_ay * v_dy) / v_len2 end;
    v_t := greatest(0, least(1, v_t));
    v_flat := round((v_alat + v_t * (v_blat - v_alat))::numeric, 3);
    v_flon := round((v_alon + v_t * (v_blon - v_alon))::numeric, 3);
    v_d := voyage.gc_distance_nm(p_lat::float8, p_lon::float8, v_flat::float8, v_flon::float8);
    if v_best is null or v_d < v_best then
      v_best := v_d; v_best_lat := v_flat; v_best_lon := v_flon;
    end if;
  end loop;
  lat := v_best_lat; lon := v_best_lon; nm := v_best::numeric;
  return next;
end $cf$;
revoke all on function voyage.channel_foot(text, numeric, numeric) from public, anon, authenticated;

-- ── 0085. THE ROADSTEAD RULE, SUPERSEDING 0076's ──────────────────────────────────────────────
-- The 12-ring search is 0076:199-217 unchanged; what is new is what happens to the winning cell.
-- The return shape gains `channel`, so this is a DROP and a CREATE (a return type cannot be
-- replaced) with the revoke re-issued. voyage.water_snap_nm — one line over this — is untouched.
drop function voyage.water_roadstead(numeric, numeric);
create function voyage.water_roadstead(p_lat numeric, p_lon numeric)
returns table (nm numeric, lat numeric, lon numeric, channel text)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $wr$
declare
  r public.sea_raster%rowtype;
  v_row int; v_col int; ring int; dr int; dc int; rr int; cc int;
  v_best numeric := null; v_brow int; v_bcol int;
  v_blat numeric; v_blon numeric;
  v_clat numeric; v_clon numeric;
  v_nm numeric;
  v_channel text;
begin
  select * into r from public.sea_raster where id = 1;
  v_row := least(r.rows - 1, greatest(0, floor((90 - p_lat) / r.cell_deg)::int));
  v_col := ((floor((p_lon + 180) / r.cell_deg)::int % r.cols) + r.cols) % r.cols;
  if get_bit(r.cells, (v_row * r.cols + v_col) * r.bits_per_cell) = 1 then
    -- Her own cell is sailable: the candidate is the quay itself, at zero distance (0076).
    v_best := 0; v_brow := v_row; v_bcol := v_col; v_blat := p_lat; v_blon := p_lon;
  else
    for ring in 1 .. 12 loop
      for dr in -ring .. ring loop
        rr := v_row + dr;
        continue when rr < 0 or rr >= r.rows;
        for dc in -ring .. ring loop
          continue when greatest(abs(dr), abs(dc)) <> ring;
          cc := ((v_col + dc) % r.cols + r.cols) % r.cols;
          if get_bit(r.cells, (rr * r.cols + cc) * r.bits_per_cell) = 1 then
            v_clat := 90 - (rr + 0.5) * r.cell_deg;
            v_clon := -180 + (cc + 0.5) * r.cell_deg;
            v_nm := voyage.gc_distance_nm(p_lat::float8, p_lon::float8, v_clat::float8, v_clon::float8)::numeric;
            if v_best is null or v_nm < v_best then
              v_best := v_nm; v_blat := v_clat; v_blon := v_clon; v_brow := rr; v_bcol := cc;
            end if;
          end if;
        end loop;
      end loop;
      exit when v_best is not null;
    end loop;
    if v_best is null then
      -- 999 is 0047's own answer for "no water within 12 rings", kept so nothing changes here.
      nm := 999; lat := null; lon := null; channel := null; return next; return;
    end if;
  end if;
  -- 0085: was the winning cell DRY LAND that a channel carved open? Then the raster is the only
  -- thing calling it water, and the roadstead lies on the channel itself, nearest the quay.
  select c.id into v_channel from voyage.channels c
   where c.carved_cells @> to_jsonb(v_brow * r.cols + v_bcol);
  if v_channel is null then
    nm := v_best; lat := v_blat; lon := v_blon; channel := null;
  else
    select f.nm, f.lat, f.lon into nm, lat, lon from voyage.channel_foot(v_channel, p_lat, p_lon) f;
    channel := v_channel;
  end if;
  return next;
end $wr$;
revoke all on function voyage.water_roadstead(numeric, numeric) from public, anon, authenticated;

-- ── The raster is NOT rewritten ────────────────────────────────────────────────────────────────
-- The grid this run built is byte-identical to the row public.sea_raster already holds
-- (545,966 water cells, 259200 packed bytes). Re-emitting 260 KB of the same base64 would
-- claim a change this file did not make. The self-assert still reads 13 named control cells
-- back through get_bit, because "unchanged" is a measurement too.

-- ── 3. THE ROADSTEADS AND THE SAILED DISTANCES BETWEEN THEM ────────────────────────────────────
-- Replaced whole rather than merged — the 0052:92-94 precedent, exactly. Every figure in the
-- table comes from ONE pass over ONE raster, and a half-updated table would be two authorities
-- for one distance. `reaches` is now measured ROADSTEAD to ROADSTEAD, because that is the
-- passage cmd.do_sail sells after this file: a table still quoting quay to quay would advertise
-- a passage the mover refuses, which is the very thing 0047:445-448 forbids.
delete from public.sea_reaches;

insert into public.sea_reaches (port_id, code, snap_nm, roadstead_lat, roadstead_lon, reaches)
