    ('ZAN', 0.00, -6.170, 39.200, '{"ACA":10566.9,"ACC":5046.6,"ADE":1703.6,"AGA":7135,"ALE":9348.9,"ALG":7971,"AMB":5332.2,"AMS":8663.3,"ANC":9164.8,"ANG":7600,"ANT":9343.4,"ARK":10554.1,"ARP":8633.9,"AYU":4884.7,"BAB":1811.2,"BAN":3436.3,"BAR":8061.2,"BAS":2455.7,"BEI":9567.6,"BEL":6734.2,"BER":9078.2,"BIL":8166.5,"BIS":8110.3,"BND":5417.5,"BNT":3993.2,"BOR":8289.6,"BOS":9169.6,"BRI":7695.6,"BRS":8474.3,"BRU":8578.1,"BSR":2965.4,"BUE":6089.4,"BUS":6565.9,"CAD":7515.8,"CAG":8282.2,"CAL":4926.9,"CAP":5042.1,"CAR":8723.6,"CEB":5545,"CEU":7557.6,"CHE":2816.5,"CHI":3632.4,"CHS":9137.7,"CID":6230.3,"CLL":8654.9,"CLS":8524.9,"COL":2545.3,"COP":9181.8,"COR":8866,"CPT":2442.2,"CRK":8289.9,"CSV":7450,"CUM":7902.6,"DBR":9003.2,"DIL":5151.8,"DIU":2473.1,"DLD":5679.7,"DOG":8731.4,"DRK":5748,"DUB":8419.1,"ELM":5042.1,"FAM":9522.1,"FEO":9722.2,"FNC":7101.7,"FUK":6518.7,"FUZ":5767.8,"GAL":2565,"GBK":8496.9,"GDA":9407.1,"GIB":7553.9,"GOA":8394,"GOR":6018.8,"GUA":5489.4,"HAD":1437.1,"HAG":6736.7,"HAM":8906.3,"HAN":5315.8,"HAV":9232.3,"HER":9055,"HIR":6474.3,"HLT":7529.2,"HNL":9970.7,"HOI":5051,"HON":5436.5,"HOO":3559.7,"HOR":2455.7,"HRN":8680.2,"INC":6574.1,"ISL":557.9,"IST":9348.2,"IZM":9142.4,"JAF":2623.2,"JAK":4037.8,"JAM":9266.2,"JED":2406.1,"JEJ":6362,"KAG":6395.5,"KAL":9449.6,"KAN":2403.2,"KAR":2456.9,"KHA":2558.6,"KIL":175.9,"KIN":8700.9,"KOC":2409.4,"KOL":2401.3,"KOZ":2411.5,"KUP":5032.9,"LAG":5022.2,"LAR":8239.1,"LEH":8427.3,"LEI":8873.5,"LIS":7537.2,"LIV":8420.9,"LNG":9958.3,"LON":8574.8,"LPA":6844.5,"LUA":4098,"LUB":9265.3,"MAC":5427.5,"MAK":4787.5,"MAL":3908.5,"MAN":2744.6,"MAS":2101.3,"MAT":7177.6,"MCH":3018.6,"MES":8572.5,"MID":8594.1,"MLE":2148.7,"MLG":7637.3,"MLN":196.2,"MNG":2402.7,"MNL":5487.5,"MOC":1839,"MOG":617.8,"MOK":6415.8,"MOM":129.2,"MRS":8243.4,"MUM":2492.7,"MUS":2218.8,"MYE":3718.8,"NAG":6421.9,"NAH":6074.5,"NAM":6635.7,"NAN":8263,"NAP":8520.2,"NEW":9227.5,"NIN":6098.1,"NUU":9240.7,"OLD":2429.4,"OPO":7683.9,"ORA":7790.1,"OSA":6696.1,"OUI":5042.5,"PAL":8437.5,"PAN":9938.6,"PAR":7313.6,"PAT":8864.3,"PLM":8004.9,"PLO":1376.8,"PLY":8306.4,"PON":7534.3,"POR":8725.7,"PRT":8908.9,"PTH":8411.8,"PTT":4495.2,"PUL":2866.8,"QUA":5695.2,"QUE":9419.2,"REC":5732.1,"REY":9013.2,"RHO":9199.4,"RIG":9634.3,"RIO":5670.6,"ROT":8620.7,"RRF":2299.8,"SAF":7244.9,"SAI":6175.3,"SAK":6696.1,"SAL":7411.6,"SAN":8232.3,"SAO":4642.6,"SET":7520.7,"SGO":8368.2,"SGS":8247.5,"SHI":6551.2,"SKC":3460.1,"SLV":5740.4,"SNL":7530.3,"SNT":8343.9,"SOF":1023.8,"SOG":7539.8,"SOH":2438.6,"SOM":3806.6,"SOS":5801.9,"SOY":4208.9,"SPL":9076.4,"SRT":2550.6,"STA":9244.8,"STG":8596.5,"STJ":8637.9,"STO":9525,"SUA":2339.5,"SUE":3009.9,"SUR":4411.5,"SVQ":7570.2,"SYD":6440.7,"TAI":5641.3,"TAL":9664.6,"TAN":7521.3,"TEN":6855,"TER":5433.6,"THA":3708.8,"THE":9215.7,"TID":5452.9,"TOK":6919.6,"TON":6502.2,"TOR":8913.1,"TOU":8259.9,"TRA":9874.9,"TRI":9594.8,"TRO":9322,"TRP":8650.3,"TSU":6493.3,"TUN":8352.4,"TUR":9636.5,"ULS":6598.3,"VAL":7936.2,"VAR":10040.1,"VEN":9263.9,"VER":9890.7,"VIS":9434.1,"VLL":8549.1,"VLP":7418,"WIL":8243.8,"XIA":5655.1,"YEO":6467.7,"ZAK":8849.7}')
  ) as v(code, snap_nm, rlat, rlon, reaches)
  join public.ports p on p.code = v.code;

-- ── SELF-ASSERT ────────────────────────────────────────────────────────────────────────────────
do $$
declare
  r          public.sea_raster%rowtype;
  c_probe    constant uuid := '00000000-0085-4000-8000-000000000001';
  -- The Lisbon -> Cadiz course this run's own pathfinder produced, ROADSTEAD to ROADSTEAD.
  c_course   constant jsonb := '[[38.625,-9.625],[36.875,-9.125],[36.625,-8.875],[36.375,-6.375]]'::jsonb;
  -- and the course the PROBE sails: LIS to SET, whose roadstead lies 26.17 nm off her
  -- quay — further than course_join_nm, which is what makes the destination hunk provable.
  c_probe_course constant jsonb := '[[38.625,-9.625],[38.125,-9.125]]'::jsonb;
  c_brs_ams  constant jsonb := '[[51.45,-2.6],[51.375,-4.625],[50.375,-5.625],[50.125,-5.875],[49.875,-5.625],[50.625,0.625],[52.875,4.375]]'::jsonb;
  v_n        int;
  v_bad      int;
  v_far      int;
  v_ports    int;
  v_missing  int;
  v_grants   int;
  v_nm       numeric;
  v_ref      text;
  v_isthmus  text;
  v_canal    text;
  v_gc       numeric;
  v_ayu_rlat numeric; v_ayu_rlon numeric;
  v_tha_rlat numeric; v_tha_rlon numeric;
  v_snap     numeric;
  v_road     jsonb;
  v_def      text;
  v_before   text;
  v_acl_b    text;
  v_acl_a    text;
  v_pan_lat  numeric; v_pan_lon numeric; v_pan_snap numeric; v_pan_rlat numeric; v_pan_rlon numeric;
  v_por_lat  numeric; v_por_lon numeric; v_por_snap numeric; v_por_rlat numeric; v_por_rlon numeric;
  v_city_line jsonb; v_road_line jsonb;
  v_player   uuid;
  v_fleet    uuid;
  v_res      jsonb;
  v_lat      numeric; v_lon numeric;
  v_eta      timestamptz;
  v_docked   uuid;
  v_status   text;
  v_walked   int;
begin
  -- (a) NOT VACUOUS: the table is populated, and EVERY port has a row. Every check below runs
  --     over these rows, and 0049:85 / 0065:4329 already assert this equality — it is asserted
  --     again HERE, before anything relies on it, because world.snapshot is about to serve a
  --     key that has no null arm.
  select count(*) into v_ports from public.ports;
  select count(*) into v_n from public.sea_reaches;
  if v_ports < 200 or v_n <> v_ports then
    raise exception '0085 self-assert FAIL: % reach row(s) for % port(s) — every check below would pass over nothing', v_n, v_ports;
  end if;
  select count(*) into v_missing from public.ports p
   where not exists (select 1 from public.sea_reaches sr where sr.port_id = p.id);
  if v_missing <> 0 then
    raise exception '0085 self-assert FAIL: % port(s) carry no sea_reaches row, so world.snapshot would serve them a null roadstead', v_missing;
  end if;

  -- (b) THE LINE DRAWN IS THE DISTANCE MEASURED. The chart draws the helper line from the quay
  --     to the roadstead and prints snap_nm beside it; if those are two numbers, the picture is
  --     about a quantity nothing computed (src/chart/route.ts:8-12). 0.01 nm is the rounding of
  --     snap_nm's own two decimal places, not a tolerance for error.
  select count(*) into v_bad
    from public.sea_reaches sr join public.ports p on p.id = sr.port_id
   where abs(voyage.gc_distance_nm(p.lat::float8, p.lon::float8,
              sr.roadstead_lat::float8, sr.roadstead_lon::float8)::numeric - sr.snap_nm) > 0.01;
  if v_bad <> 0 then
    raise exception '0085 self-assert FAIL: % place(s) whose helper line is not snap_nm long — the line drawn would not be the distance measured', v_bad;
  end if;

  -- (c) A PORT ON ITS OWN WATER IS ITS OWN ROADSTEAD — and that is not the whole table.
  select count(*) into v_bad
    from public.sea_reaches sr join public.ports p on p.id = sr.port_id
   where sr.snap_nm = 0 and (sr.roadstead_lat <> p.lat or sr.roadstead_lon <> p.lon);
  if v_bad <> 0 then
    raise exception '0085 self-assert FAIL: % place(s) snap 0 nm and yet hold a roadstead off the quay', v_bad;
  end if;
  select count(*) into v_far from public.sea_reaches where snap_nm > 0;
  if v_far < 100 then
    raise exception '0085 self-assert FAIL: only % place(s) hold a roadstead off the quay — 176 were measured, and a table of quay coordinates would pass (b) and (c) vacuously', v_far;
  end if;

  -- (d) EVERY ROADSTEAD IS A FIXED POINT OF THE RULE — asked of the raster and the channels
  --     themselves rather than of the generator that wrote the column: its own cell is sailable
  --     water and, since 0085, if that cell is one the carve opened, the point lies ON the
  --     channel (a carved-cell point off the channel — the Kent centre — measures its distance
  --     to the line here, and is refused).
  select count(*) into v_bad from public.sea_reaches sr
   where voyage.water_snap_nm(sr.roadstead_lat, sr.roadstead_lon) <> 0;
  if v_bad <> 0 then
    raise exception '0085 self-assert FAIL: % roadstead(s) are not where the rule puts a roadstead — off sailable water, or in a carved cell but off its channel', v_bad;
  end if;

  -- (e) THE GENERATOR AND THE SQL ARE ONE RULE. This is why water_snap_nm's body was folded
  --     down: a cross-implementation check over every row, not a re-read of what was written.
  select count(*) into v_bad
    from public.sea_reaches sr join public.ports p on p.id = sr.port_id
   cross join lateral voyage.water_roadstead(p.lat, p.lon) wr
   where wr.lat <> sr.roadstead_lat or wr.lon <> sr.roadstead_lon;
  if v_bad <> 0 then
    raise exception '0085 self-assert FAIL: % row(s) where the seeded roadstead POINT is not what voyage.water_roadstead answers — the Node generator and the SQL rule have drifted', v_bad;
  end if;
  -- and the DISTANCE, to the two decimal places snap_nm is stored at. The first draft of this
  -- check compared the two exactly and went red on all 176 off-quay rows on its own first
  -- apply: water_roadstead answers in full float precision and the column keeps two decimals.
  -- The tolerance is that rounding, not room for a disagreement.
  select count(*) into v_bad
    from public.sea_reaches sr join public.ports p on p.id = sr.port_id
   cross join lateral voyage.water_roadstead(p.lat, p.lon) wr
   where abs(wr.nm - sr.snap_nm) > 0.01;
  if v_bad <> 0 then
    raise exception '0085 self-assert FAIL: % row(s) where the seeded snap_nm is not what voyage.water_roadstead measures', v_bad;
  end if;

  -- and THE CHANNEL: exactly the places this run measured take their roadstead on a channel,
  -- pinned to the measurement (25) rather than to a floor a wrong table could clear.
  select count(*) into v_n
    from public.sea_reaches sr join public.ports p on p.id = sr.port_id
   cross join lateral voyage.water_roadstead(p.lat, p.lon) wr
   where wr.channel is not null;
  if v_n <> 25 then
    raise exception '0085 self-assert FAIL: % place(s) take their roadstead on a channel; this run measured 25 (ARP AYU BEL BOR BRS BSR BUE COP GUA HAM HOO KHA LAR LON MID NAN OSA QUE RIG SAK SNL SUE SVQ TAL THA)', v_n;
  end if;

  -- (p) THE CHANNELS TABLE IS THE AUTHORED LIST, WHOLE. 27 rows, 202 carved cells between them,
  --     no cell carved by two channels (or the rule would have two polylines to choose from), and
  --     every carved cell reads WATER in the raster — the carve this table describes is the carve
  --     the raster carries.
  select count(*), coalesce(sum(opens_land), 0) into v_n, v_bad from voyage.channels;
  if v_n <> 27 or v_bad <> 202 then
    raise exception '0085 self-assert FAIL: voyage.channels holds % channel(s) opening % cell(s) of land; this run seeded 27 opening 202', v_n, v_bad;
  end if;
  select count(*) into v_bad from (
    select x from voyage.channels c cross join lateral jsonb_array_elements(c.carved_cells) x
     group by x having count(*) > 1) d;
  if v_bad <> 0 then
    raise exception '0085 self-assert FAIL: % carved cell(s) belong to two channels — the roadstead rule needs one channel per cell', v_bad;
  end if;
  select * into r from public.sea_raster where id = 1;
  select count(*) into v_bad
    from voyage.channels c cross join lateral jsonb_array_elements_text(c.carved_cells) x
   where get_bit(r.cells, x::int * r.bits_per_cell) <> 1;
  if v_bad <> 0 then
    raise exception '0085 self-assert FAIL: % carved cell(s) read as LAND in the raster — voyage.channels describes a carve the raster does not carry', v_bad;
  end if;

  -- (q) EVERY CHANNEL ROADSTEAD LIES ON ITS CHANNEL — the SQL half of the land proof. The
  --     generator proved, over data/world-110m.json, that no off-quay roadstead sits inside a
  --     coastline polygon unless a channel runs under it; this proves the "runs under it": the
  --     seeded point is within 0.1 nm of the polyline (3-dp rounding is under 0.06 nm). Asked
  --     over rows the FUNCTION calls channel rows, and the count is pinned above, so it is not
  --     vacuous.
  select count(*) into v_bad
    from (select sr.roadstead_lat as rlat, sr.roadstead_lon as rlon, wr.channel
            from public.sea_reaches sr join public.ports p on p.id = sr.port_id
           cross join lateral voyage.water_roadstead(p.lat, p.lon) wr
           where wr.channel is not null) x
   cross join lateral voyage.channel_foot(x.channel, x.rlat, x.rlon) f
   where f.nm > 0.1;
  if v_bad <> 0 then
    raise exception '0085 self-assert FAIL: % channel roadstead(s) do not lie on their channel — a point off the polyline is a point the land data calls land', v_bad;
  end if;

  -- (r) THE NAMED CONTROL: LONDON. The owner's example. Her roadstead lies on the Thames line
  --     within 2 nm, her snap is between 0.5 and 15 nm, and it is NOT the cell centre 0079
  --     seeded (51.375, -0.125), 8.11 nm into Kent — at least 5 nm from it.
  select sr.snap_nm, sr.roadstead_lat, sr.roadstead_lon, wr.channel
    into v_snap, v_lat, v_lon, v_ref
    from public.sea_reaches sr join public.ports p on p.id = sr.port_id
   cross join lateral voyage.water_roadstead(p.lat, p.lon) wr
   where sr.code = 'LON';
  if v_snap is null then
    raise exception '0085 self-assert FAIL: LON carries no roadstead, so the named control proves nothing';
  end if;
  if v_ref is distinct from 'thames-scheldt' then
    raise exception '0085 self-assert FAIL: London is reached from [%], not from the Thames channel', coalesce(v_ref, 'no channel');
  end if;
  if (select f.nm from voyage.channel_foot('thames-scheldt', v_lat, v_lon) f) > 2 then
    raise exception '0085 self-assert FAIL: London''s roadstead (%, %) lies more than 2 nm off the Thames line', v_lat, v_lon;
  end if;
  if v_snap < 0.5 or v_snap > 15 then
    raise exception '0085 self-assert FAIL: London''s roadstead is % nm off the quay — outside the 0.5 to 15 nm a Thames roadstead can be', v_snap;
  end if;
  if voyage.gc_distance_nm(v_lat::float8, v_lon::float8, 51.375, -0.125) < 5 then
    raise exception '0085 self-assert FAIL: London''s roadstead (%, %) is still the Kent cell centre 0079 seeded', v_lat, v_lon;
  end if;

  -- (s) THE RIVER PORTS, pinned to this run's measurement (0.01 nm is snap_nm's own rounding):
  --     Antwerp, Seville, Nantes and Bordeaux take a roadstead OFF the quay for the first time;
  --     Bristol's quay is a vertex of the Severn channel, so hers stays the quay at 0 nm — the
  --     rule applied to her too, and answered zero.
  select sr.snap_nm, wr.channel into v_snap, v_ref
    from public.sea_reaches sr join public.ports p on p.id = sr.port_id
   cross join lateral voyage.water_roadstead(p.lat, p.lon) wr where sr.code = 'ARP';
  if v_snap is null or abs(v_snap - 1.10) > 0.01 or v_ref is distinct from 'thames-scheldt' then
    raise exception '0085 self-assert FAIL: Antwerp is % nm off the quay on [%]; this run measured 1.10 nm on thames-scheldt', v_snap, coalesce(v_ref, 'no channel');
  end if;
  select sr.snap_nm, wr.channel into v_snap, v_ref
    from public.sea_reaches sr join public.ports p on p.id = sr.port_id
   cross join lateral voyage.water_roadstead(p.lat, p.lon) wr where sr.code = 'SVQ';
  if v_snap is null or abs(v_snap - 0.67) > 0.01 or v_ref is distinct from 'guadalquivir' then
    raise exception '0085 self-assert FAIL: Seville is % nm off the quay on [%]; this run measured 0.67 nm on guadalquivir', v_snap, coalesce(v_ref, 'no channel');
  end if;
  select sr.snap_nm, wr.channel into v_snap, v_ref
    from public.sea_reaches sr join public.ports p on p.id = sr.port_id
   cross join lateral voyage.water_roadstead(p.lat, p.lon) wr where sr.code = 'BRS';
  if v_snap is null or abs(v_snap - 0.00) > 0.01 or v_ref is distinct from 'severn' then
    raise exception '0085 self-assert FAIL: Bristol is % nm off the quay on [%]; this run measured 0.00 nm on severn', v_snap, coalesce(v_ref, 'no channel');
  end if;
  select sr.snap_nm, wr.channel into v_snap, v_ref
    from public.sea_reaches sr join public.ports p on p.id = sr.port_id
   cross join lateral voyage.water_roadstead(p.lat, p.lon) wr where sr.code = 'NAN';
  if v_snap is null or abs(v_snap - 6.23) > 0.01 or v_ref is distinct from 'gironde' then
    raise exception '0085 self-assert FAIL: Nantes is % nm off the quay on [%]; this run measured 6.23 nm on gironde', v_snap, coalesce(v_ref, 'no channel');
  end if;
  select sr.snap_nm, wr.channel into v_snap, v_ref
    from public.sea_reaches sr join public.ports p on p.id = sr.port_id
   cross join lateral voyage.water_roadstead(p.lat, p.lon) wr where sr.code = 'BOR';
  if v_snap is null or abs(v_snap - 3.70) > 0.01 or v_ref is distinct from 'gironde' then
    raise exception '0085 self-assert FAIL: Bordeaux is % nm off the quay on [%]; this run measured 3.70 nm on gironde', v_snap, coalesce(v_ref, 'no channel');
  end if;

  -- (t) POSITIVE CONTROL for (e) and (q): put London's roadstead BACK where 0079 had it — the
  --     Kent cell centre, with snap_nm re-measured so (b) still holds — and require the point
  --     cross-check (e) AND the on-channel check (q) to each find it EXACTLY ONCE. Rolled back.
  begin
    update public.sea_reaches sr
       set roadstead_lat = 51.375, roadstead_lon = -0.125,
           snap_nm = round(voyage.gc_distance_nm(p.lat::float8, p.lon::float8, 51.375, -0.125)::numeric, 2)
      from public.ports p where p.id = sr.port_id and sr.code = 'LON';
    select count(*) into v_bad
      from public.sea_reaches sr join public.ports p on p.id = sr.port_id
     cross join lateral voyage.water_roadstead(p.lat, p.lon) wr
     where wr.lat <> sr.roadstead_lat or wr.lon <> sr.roadstead_lon;
    if v_bad <> 1 then
      raise exception '0085 self-assert FAIL: London''s roadstead moved back to the Kent cell centre was found % time(s) by (e), expected exactly 1', v_bad;
    end if;
    select count(*) into v_bad
      from (select sr.roadstead_lat as rlat, sr.roadstead_lon as rlon, wr.channel
              from public.sea_reaches sr join public.ports p on p.id = sr.port_id
             cross join lateral voyage.water_roadstead(p.lat, p.lon) wr
             where wr.channel is not null) x
     cross join lateral voyage.channel_foot(x.channel, x.rlat, x.rlon) f
     where f.nm > 0.1;
    if v_bad <> 1 then
      raise exception '0085 self-assert FAIL: London''s roadstead moved back to the Kent cell centre was found % time(s) by (q), expected exactly 1 — the on-channel check cannot bite', v_bad;
    end if;
    raise exception '__PROBE_ROLLBACK__' using errcode = 'P0001';
  exception when others then
    if sqlerrm <> '__PROBE_ROLLBACK__' then raise; end if;
  end;

  -- (f) POSITIVE CONTROL #1 for (b): collapse ONE roadstead back onto its own quay — the exact
  --     regression this design fears — and require (b) to find it, EXACTLY ONCE. Rolled back.
  begin
    update public.sea_reaches sr
       set roadstead_lat = p.lat, roadstead_lon = p.lon
      from public.ports p
     where p.id = sr.port_id
       and sr.code = (select code from public.sea_reaches order by snap_nm desc, code limit 1);
    select count(*) into v_bad
      from public.sea_reaches sr join public.ports p on p.id = sr.port_id
     where abs(voyage.gc_distance_nm(p.lat::float8, p.lon::float8,
                sr.roadstead_lat::float8, sr.roadstead_lon::float8)::numeric - sr.snap_nm) > 0.01;
    if v_bad <> 1 then
      raise exception '0085 self-assert FAIL: a roadstead collapsed onto its own quay was found % time(s), expected exactly 1 — check (b) cannot bite and every green above it is vacuous', v_bad;
    end if;
    raise exception '__PROBE_ROLLBACK__' using errcode = 'P0001';
  exception when others then
    if sqlerrm <> '__PROBE_ROLLBACK__' then raise; end if;
  end;

  -- (g) THE HEADLINE, AND ITS OWN POSITIVE CONTROL — the isthmus of Panama.
  select p.lat, p.lon, sr.snap_nm, sr.roadstead_lat, sr.roadstead_lon
    into v_pan_lat, v_pan_lon, v_pan_snap, v_pan_rlat, v_pan_rlon
    from public.ports p join public.sea_reaches sr on sr.port_id = p.id where p.code = 'PAN';
  select p.lat, p.lon, sr.snap_nm, sr.roadstead_lat, sr.roadstead_lon
    into v_por_lat, v_por_lon, v_por_snap, v_por_rlat, v_por_rlon
    from public.ports p join public.sea_reaches sr on sr.port_id = p.id where p.code = 'POR';
  if v_pan_rlat is null or v_por_rlat is null then
    raise exception '0085 self-assert FAIL: PAN or POR carries no roadstead, so the headline proves nothing';
  end if;
  -- CONTROL, MUST STAY GREEN: the OLD quay-to-quay line is still ACCEPTED under the OLD
  -- allowance. If it ever stops being accepted, the defect this file claims to close was not
  -- there and the repair below proves nothing — so the file says so instead of shipping a boast.
  v_city_line := jsonb_build_array(jsonb_build_array(v_pan_lat, v_pan_lon),
                                   jsonb_build_array(v_por_lat, v_por_lon));
  if voyage.path_refusal(v_city_line, v_pan_lat, v_pan_lon, v_por_lat, v_por_lon,
                         public.wc_num('course_join_nm'),
                         v_pan_snap + 25, v_por_snap + 25) is not null then
    raise exception '0085 self-assert FAIL: the quay-to-quay isthmus line is ALREADY refused under the old allowance — the defect this file claims to close is not there';
  end if;
  -- THE REPAIR: the same passage between the two ROADSTEADS, under the flat allowance.
  v_road_line := jsonb_build_array(jsonb_build_array(v_pan_rlat, v_pan_rlon),
                                   jsonb_build_array(v_por_rlat, v_por_rlon));
  v_isthmus := voyage.path_refusal(v_road_line, v_pan_rlat, v_pan_rlon, v_por_rlat, v_por_rlon,
                                   public.wc_num('course_join_nm'), 25, 25);
  if v_isthmus is null or v_isthmus not like 'E_LAND%' then
    raise exception '0085 self-assert FAIL: the line from the Panama City roads to the Port Royal roads is not refused as E_LAND (got %) — the isthmus is open and the short way across it is still purchasable', coalesce(v_isthmus, 'ACCEPTED');
  end if;
  -- and the table agrees with the law: the reach is the long way round now.
  v_nm := (select (reaches->>'POR')::numeric from public.sea_reaches where code = 'PAN');
  if v_nm is null or v_nm < 5000 then
    raise exception '0085 self-assert FAIL: PAN->POR is served at % nm — the quay would advertise a passage the mover refuses', v_nm;
  end if;

  -- (g2) THE CANAL THAT WAS NEVER DUG IS FILLED IN — this file's OWN headline.
  -- (g) proves the isthmus of Panama, which 0076 closed and which this file must not reopen.
  -- What THIS file changes is the Tenasserim isthmus, and a migration proves its own claim.
  --
  -- THREE THINGS, AND THE THIRD IS THE ONE THAT MATTERS TO A PLAYER:
  --   1. every reclaimed cell reads as LAND in the raster and answers NO SEA — both rasters
  --      moved, which is precisely what stopped the first attempt at this repair;
  --   2. the straight line between the two roadsteads is refused E_LAND, so the short way
  --      across the peninsula cannot be bought;
  --   3. the table quotes the long way round, and it is quoted at the number this run
  --      MEASURED rather than at a floor a wrong raster could also clear.
  select sr.roadstead_lat, sr.roadstead_lon into v_ayu_rlat, v_ayu_rlon
    from public.sea_reaches sr where sr.code = 'AYU';
  select sr.roadstead_lat, sr.roadstead_lon into v_tha_rlat, v_tha_rlon
    from public.sea_reaches sr where sr.code = 'THA';
  v_road_line := jsonb_build_array(jsonb_build_array(v_ayu_rlat, v_ayu_rlon),
                                   jsonb_build_array(v_tha_rlat, v_tha_rlon));
  v_canal := voyage.path_refusal(v_road_line, v_ayu_rlat, v_ayu_rlon, v_tha_rlat, v_tha_rlon,
                                 public.wc_num('course_join_nm'), 25, 25);
  if v_canal is null or v_canal not like 'E_LAND%' then
    raise exception '0085 self-assert FAIL: the line from the Ayutthaya roads to the Thanlyin roads is not refused as E_LAND (got %) — the canal through the Tenasserim mountains is still open', coalesce(v_canal, 'ACCEPTED');
  end if;
  -- AND THE TABLE AGREES WITH THE LAW. Pinned to the measurement, not to a floor: a raster that
  -- closed the canal in the wrong place would clear any floor and still be wrong.
  v_nm := (select (reaches->>'THA')::numeric from public.sea_reaches where code = 'AYU');
  if v_nm is null or abs(v_nm - 1950.8) > 0.5 then
    raise exception '0085 self-assert FAIL: AYU->THA is served at % nm; this run measured 1950.8 nm the long way round', v_nm;
  end if;
  -- The positive control, and the whole point: it is FAR longer than the straight line. The
  -- carved canal sold this pair 364.5 nm against a great circle of about 300 — a shortcut that
  -- looked plausible precisely because it was near the direct distance.
  v_gc := voyage.gc_distance_nm(v_ayu_rlat, v_ayu_rlon, v_tha_rlat, v_tha_rlon);
  if v_nm < v_gc * 3 then
    raise exception '0085 self-assert FAIL: AYU->THA sails % nm against a great circle of % — that is not around a peninsula, it is through one', v_nm, v_gc;
  end if;

  -- (h) THE WIRE CARRIES IT, FOR EVERY PORT.
  select count(*) into v_bad
    from jsonb_array_elements(world.snapshot()->'ports') p
   where p->'roadstead' is null or p->'roadstead'->>'lat' is null
      or p->'roadstead'->>'lon' is null or p->'roadstead'->>'nm'  is null;
  if v_bad <> 0 then
    raise exception '0085 self-assert FAIL: % served port(s) carry no roadstead — a client would have to compute one', v_bad;
  end if;
  select p->'roadstead' into v_road from jsonb_array_elements(world.snapshot()->'ports') p
   where p->>'code' = 'AMS';
  if (v_road->>'nm')::numeric <= 20 then
    raise exception '0085 self-assert FAIL: Amsterdam is served a roadstead % nm off the quay — 35.47 was measured, and a table of zeroes serves fine and draws nothing', v_road->>'nm';
  end if;
  if (v_road->>'lat')::numeric <> (select roadstead_lat from public.sea_reaches where code = 'AMS') then
    raise exception '0085 self-assert FAIL: the served roadstead is not the stored one';
  end if;

  -- (i) A REAL HOUSE SAILS, AND HER COURSE STARTS AT THE ROADS — then she docks AT THE PORT.
  --     The 0075/0063 probe shape, rolled back. This is the owner's sentence PROVEN rather than
  --     argued, with voyage.settle untouched.
  begin
    v_player := public.new_house(c_probe, 'Casa das Roadas', 'PRT');
    perform cmd.assume_identity(c_probe);
    select id into v_fleet from public.fleets where player_id = v_player;
    -- Pinned for the reason 0037, 0063 and 0075 pin it: a hazard drawn on this passage would
    -- delay her and this probe would be measuring the dice rather than the geometry.
    update public.world_config set value = to_jsonb(0.0) where key = 'hazard_p_max';
    perform cmd.do_provision(v_fleet, jsonb_build_object('mode', 'FULL'));
    -- A REFUSAL IS AN ENVELOPE, NOT AN EXCEPTION (0008).
    v_res := cmd.issue(v_fleet, 'SAIL TO SET', null, c_probe_course);
    if coalesce(v_res->>'ok', 'false') <> 'true' then
      raise exception '0085 self-assert FAIL: the probe could not put to sea on a roadstead-to-roadstead course: [%: %]',
        v_res->>'error_code', v_res->>'error_message';
    end if;
    perform cmd.advance(v_fleet);
    select (path->0->'a'->>0)::numeric, (path->0->'a'->>1)::numeric, eta
      into v_lat, v_lon, v_eta
      from public.voyages where fleet_id = v_fleet and status = 'SAILING';
    if v_lat is null then
      raise exception '0085 self-assert FAIL: the probe never put a voyage to sea, so this proves nothing';
    end if;
    if v_lat is distinct from (select roadstead_lat from public.sea_reaches where code = 'LIS')
       or v_lon is distinct from (select roadstead_lon from public.sea_reaches where code = 'LIS') then
      raise exception '0085 self-assert FAIL: her course begins at (%, %) and not at Lisbon''s roadstead (%, %) — the mover still departs from the quay',
        v_lat, v_lon,
        (select roadstead_lat from public.sea_reaches where code = 'LIS'),
        (select roadstead_lon from public.sea_reaches where code = 'LIS');
    end if;
    select (path->(jsonb_array_length(path)-1)->'b'->>0)::numeric into v_lat
      from public.voyages where fleet_id = v_fleet and status = 'SAILING';
    if v_lat is distinct from (select roadstead_lat from public.sea_reaches where code = 'SET') then
      raise exception '0085 self-assert FAIL: her course ends at % and not at Setubal''s roadstead', v_lat;
    end if;
    select total_nm into v_nm from public.voyages where fleet_id = v_fleet and status = 'SAILING';
    if v_nm is null or v_nm <= 0 then
      raise exception '0085 self-assert FAIL: a course of % nm', v_nm;
    end if;
    -- THE OWNER'S SENTENCE. She reaches the point, and voyage.settle — untouched by this file —
    -- docks her AT THE PORT.
    perform voyage.settle(v_fleet, v_eta + interval '1 second');
    select port_id, status into v_docked, v_status from public.fleets where id = v_fleet;
    if v_status <> 'DOCKED' or v_docked is distinct from (select id from public.ports where code = 'SET') then
      raise exception '0085 self-assert FAIL: she reached the Setubal roads and is [%] at [%] — arriving at the roadstead must dock her at the port itself',
        v_status, coalesce((select code from public.ports where id = v_docked), 'nowhere');
    end if;
    -- AND THE GUARD WALKS HER. Non-vacuity is the caller's duty (the guard's own header).
    select voyages_walked into v_walked from voyage.assert_paths_water();
    if v_walked < 1 then
      raise exception '0085 self-assert FAIL: the land guard walked % course(s) — it is asserting over nothing', v_walked;
    end if;
    -- POSITIVE CONTROL #2 FOR THE GRANDFATHER CLAUSE, both directions on ONE planted voyage:
    -- the quay-to-quay isthmus passage, which is legal under the OLD allowance and land under
    -- the NEW one. Dated BEFORE this migration it must be walked and accepted; dated after, the
    -- same row must be refused as land.
    insert into public.voyages (fleet_id, player_id, path, total_nm, speed_profile,
                                departed_at, eta, status, last_settled_day, origin_port_id, dest_port_id)
    select v_fleet, v_player, s.segs,
           (select sum((x->>'nm')::numeric) from jsonb_array_elements(s.segs) x),
           '[4.5]'::jsonb, timestamptz '2000-01-01', timestamptz '2000-01-02',
           'ARRIVED', 1,
           (select id from public.ports where code = 'PAN'),
           (select id from public.ports where code = 'POR')
      from (select voyage.segments_from_course(v_city_line) as segs) s;
    select voyages_walked into v_walked from voyage.assert_paths_water();
    if v_walked < 2 then
      raise exception '0085 self-assert FAIL: the grandfathered isthmus voyage was not walked (% course(s)) — the guard skipped it rather than accepting it', v_walked;
    end if;
    update public.voyages set departed_at = now(), eta = now() + interval '1 hour'
     where fleet_id = v_fleet and status = 'ARRIVED' and dest_port_id = (select id from public.ports where code = 'POR');
    begin
      perform * from voyage.assert_paths_water();
      raise exception '0085 self-assert FAIL: the SAME isthmus course dated after this migration was still accepted — the guard kept the hole this file closed';
    exception when others then
      if sqlerrm like '0085 self-assert FAIL%' then raise; end if;
      if position('E_LAND' in sqlerrm) = 0 then
        raise exception '0085 self-assert FAIL: the guard refused the post-cutoff isthmus voyage for the wrong reason: %', sqlerrm;
      end if;
    end;
    raise exception '__PROBE_ROLLBACK__' using errcode = 'P0001';
  exception when others then
    if sqlerrm <> '__PROBE_ROLLBACK__' then raise; end if;
  end;

  -- (j) POSTURE. Both halves, per README §3: a TABLE write grant and an EXECUTE on a
  --     SECURITY DEFINER writer are two different doors, and 0018 exists because the first read
  --     an honest zero for seventeen migrations while the second was open.
  select count(*) into v_grants from public.client_write_grants();
  if v_grants <> 0 then raise exception '0085 self-assert FAIL: % client write grant(s)', v_grants; end if;
  select count(*) into v_grants from public.client_executable_writers();
  if v_grants <> 0 then raise exception '0085 self-assert FAIL: % client-executable writer(s)', v_grants; end if;
  if not has_table_privilege('authenticated', 'public.sea_reaches', 'select')
     or has_function_privilege('anon', 'voyage.water_roadstead(numeric, numeric)', 'execute')
     or has_function_privilege('authenticated', 'voyage.water_roadstead(numeric, numeric)', 'execute')
     or has_function_privilege('authenticated', 'voyage.water_snap_nm(numeric, numeric)', 'execute')
     or has_function_privilege('authenticated', 'voyage.channel_foot(text, numeric, numeric)', 'execute')
     or has_function_privilege('anon', 'voyage.channel_foot(text, numeric, numeric)', 'execute')
     or has_table_privilege('authenticated', 'voyage.channels', 'select')
     or has_table_privilege('anon', 'voyage.channels', 'select')
     or has_function_privilege('anon', 'world.snapshot()', 'execute')
     or not has_function_privilege('authenticated', 'world.snapshot()', 'execute') then
    raise exception '0085 self-assert FAIL: the grant posture is wrong — the roadstead rule is server-only and the snapshot is the client''s';
  end if;

  -- ── AND THE TABLE'S OWN PROPERTIES, because this file rewrote every row of it ────────────────
  -- (k) THE RASTER IS THERE AND THE BIT ORDER IS THE ONE THE CLIENT PACKS. 13 control cells,
  --     each a named piece of the world, read through get_bit — the same read the sampler uses.
  select * into r from public.sea_raster where id = 1;
  if r.cols <> 1440 or r.rows <> 720 or r.bits_per_cell <> 2 or octet_length(r.cells) <> 259200 then
    raise exception '0085 self-assert FAIL: the raster is % x % at % bit(s) with % bytes — expected 1440 x 720 at 2 with 259200', r.cols, r.rows, r.bits_per_cell, octet_length(r.cells);
  end if;
  if get_bit(r.cells, 692320) <> 1 then
    raise exception '0085 self-assert FAIL: the mid-Atlantic (30, -40) reads %, expected 1', get_bit(r.cells, 692320);
  end if;
  if get_bit(r.cells, 583164) <> 0 then
    raise exception '0085 self-assert FAIL: the middle of Iberia (39.5, -4.5) reads %, expected 0', get_bit(r.cells, 583164);
  end if;
  if get_bit(r.cells, 566152) <> 1 then
    raise exception '0085 self-assert FAIL: the Bosphorus channel (41, 29) reads %, expected 1', get_bit(r.cells, 566152);
  end if;
  if get_bit(r.cells, 175200) <> 0 then
    raise exception '0085 self-assert FAIL: the Siberian arctic (ice) (75, 120) reads %, expected 0', get_bit(r.cells, 175200);
  end if;
  if get_bit(r.cells, 232160) <> 1 then
    raise exception '0085 self-assert FAIL: the Barents Sea (open — the Muscovy road) (70, 40) reads %, expected 1', get_bit(r.cells, 232160);
  end if;
  if get_bit(r.cells, 1787040) <> 0 then
    raise exception '0085 self-assert FAIL: the Antarctic pack (-65, 0) reads %, expected 0', get_bit(r.cells, 1787040);
  end if;
  if get_bit(r.cells, 900896) <> 1 then
    raise exception '0085 self-assert FAIL: the South China Sea (12, 112) reads %, expected 1', get_bit(r.cells, 900896);
  end if;
  if get_bit(r.cells, 773360) <> 0 then
    raise exception '0085 self-assert FAIL: the Sahara (23, 10) reads %, expected 0', get_bit(r.cells, 773360);
  end if;
  if get_bit(r.cells, 444934) <> 1 then
    raise exception '0085 self-assert FAIL: the Bristol Channel off Barry (51.4, -3.1) reads %, expected 1', get_bit(r.cells, 444934);
  end if;
  if get_bit(r.cells, 444938) <> 1 then
    raise exception '0085 self-assert FAIL: the Severn approach at Bristol (51.45, -2.6) reads %, expected 1', get_bit(r.cells, 444938);
  end if;
  if get_bit(r.cells, 439172) <> 0 then
    raise exception '0085 self-assert FAIL: the Welsh hills above the channel (52, -3.5) reads %, expected 0', get_bit(r.cells, 439172);
  end if;
  if get_bit(r.cells, 1717920) <> 1 then
    raise exception '0085 self-assert FAIL: the Southern Ocean at 59°S (open) (-59, 0) reads %, expected 1', get_bit(r.cells, 1717920);
  end if;
  if get_bit(r.cells, 1740960) <> 0 then
    raise exception '0085 self-assert FAIL: the pack at 61°S (closed) (-61, 0) reads %, expected 0', get_bit(r.cells, 1740960);
  end if;

  -- (l) EVERY PLACE REACHES EVERY OTHER PLACE, symmetrically. Non-vacuous by the counts
  --     themselves: the world cannot hold an island nobody can sail to.
  select count(*) into v_bad from public.sea_reaches sr
   where (select count(*) from jsonb_object_keys(sr.reaches)) <> v_ports - 1;
  if v_bad <> 0 then
    raise exception '0085 self-assert FAIL: % place(s) do not reach every other place', v_bad;
  end if;
  select count(*) into v_bad
    from public.sea_reaches a
   cross join lateral jsonb_each_text(a.reaches) e(code, nm)
    join public.sea_reaches b on b.code = e.code
   where (b.reaches->>a.code)::numeric is distinct from e.nm::numeric;
  if v_bad <> 0 then
    raise exception '0085 self-assert FAIL: % asymmetric pair reading(s)', v_bad;
  end if;

  -- (m) NO SAILED DISTANCE IS SHORTER THAN THE GREAT CIRCLE — and after this file the great
  --     circle it must clear is the one BETWEEN THE ROADSTEADS, because that is what was sailed.
  --     Comparing against the quay-to-quay line would be comparing two different passages.
  select count(*) into v_bad
    from public.sea_reaches a
   cross join lateral jsonb_each_text(a.reaches) e(code, nm)
    join public.sea_reaches b on b.code = e.code
   where a.code < e.code
     and e.nm::numeric < voyage.gc_distance_nm(a.roadstead_lat::float8, a.roadstead_lon::float8,
                                               b.roadstead_lat::float8, b.roadstead_lon::float8) * 0.995;
  if v_bad <> 0 then
    raise exception '0085 self-assert FAIL: % pair(s) sail shorter than the great circle between their roadsteads', v_bad;
  end if;

  -- (n) THE WORLD'S THREE STANDING FACTS, unmoved by the reshape: no Arctic road, no Suez, no
  --     Panama. If ending courses at the roads had quietly opened one of them, this bites.
  v_nm := (select (reaches->>'NAG')::numeric from public.sea_reaches where code = 'LIS');
  if v_nm is null or v_nm < 12000 then
    raise exception '0085 self-assert FAIL: LIS->NAG is % nm — under 12,000 means the Arctic is open again (the leg graph served 7,565 over the pole)', v_nm;
  end if;
  if (select (reaches->>'ADE')::numeric from public.sea_reaches where code = 'ALE') < 9000 then
    raise exception '0085 self-assert FAIL: ALE->ADE under 9,000 nm — a Suez Canal three centuries early';
  end if;
  if (select (reaches->>'ACA')::numeric from public.sea_reaches where code = 'VER') < 9000 then
    raise exception '0085 self-assert FAIL: VER->ACA under 9,000 nm — a Panama Canal three centuries early';
  end if;
  select snap_nm into v_snap from public.sea_reaches where code = 'BRS';
  if v_snap is null or v_snap > 20 then
    raise exception '0085 self-assert FAIL: Bristol snaps % nm to sailable water — over 20 means the Severn is land again (it was 64.55 nm to Lyme Bay)', v_snap;
  end if;

  -- (o) THE MEASURE AND THE LAW, on two real courses this run's own pathfinder produced between
  --     the very roadsteads the table now holds — accepted under the FLAT allowance, which is
  --     the allowance the re-cut mover grants. A course that needed more would mean the
  --     roadstead did not remove the need for the snap exemption.
  v_ref := voyage.path_refusal(c_course,
             (select roadstead_lat from public.sea_reaches where code = 'LIS'),
             (select roadstead_lon from public.sea_reaches where code = 'LIS'),
             (select roadstead_lat from public.sea_reaches where code = 'CAD'),
             (select roadstead_lon from public.sea_reaches where code = 'CAD'),
             public.wc_num('course_join_nm'), 25, 25);
  if v_ref is not null then
    raise exception '0085 self-assert FAIL: the real Lisbon->Cadiz roads-to-roads course was refused under the flat 25 nm allowance: %', v_ref;
  end if;
  v_ref := voyage.path_refusal(c_brs_ams,
             (select roadstead_lat from public.sea_reaches where code = 'BRS'),
             (select roadstead_lon from public.sea_reaches where code = 'BRS'),
             (select roadstead_lat from public.sea_reaches where code = 'AMS'),
             (select roadstead_lon from public.sea_reaches where code = 'AMS'),
             public.wc_num('course_join_nm'), 25, 25);
  if v_ref is not null then
    raise exception '0085 self-assert FAIL: the real Bristol->Amsterdam roads-to-roads course was refused under the flat 25 nm allowance: %', v_ref;
  end if;
  -- the negative control the sampler has carried since 0046: a straight line across Iberia.
  v_ref := voyage.path_refusal(
             jsonb_build_array(jsonb_build_array(38.71, -9.14), jsonb_build_array(41.38, 2.18)),
             38.71, -9.14, 41.38, 2.18, 15, 40, 40);
  if v_ref is null or v_ref not like 'E_LAND:%' then
    raise exception '0085 self-assert FAIL: a straight Lisbon->Barcelona line across Iberia was NOT refused as land (got [%])', coalesce(v_ref, 'null');
  end if;

  raise notice '0085 self-assert ok: A ROADSTEAD LIES ON THE CHANNEL. 25 places snap to a cell the authored carve opened — sea in the raster, land in data/world-110m.json — and every one of them now takes its roadstead ON the polyline of that channel, nearest the quay: London is reached from (51.5, -0.1) on the Thames, 1.27 nm off the quay, where 0079 seeded (51.375, -0.125), 8.11 nm into Kent. 24 roadsteads move against the applied table; 15 river ports that were their own roadstead at 0 nm now carry one off the quay, so their dotted line and ring exist for the first time (the quay at Bristol is itself a vertex of the Severn and stays at 0). The land data itself was asked in the generator: 8 off-quay roadsteads of the applied table stood inside a coastline polygon (BSR COP HAM KHA LON OSA SAK THA); 0 do now unless a channel runs under them, and (q) proves each channel roadstead is on its line. A HARBOUR IS REACHED FROM ITS ROADS. % places carry a roadstead; 176 of them lie off the quay (worst LNG 67.68 nm, AMS 35.47 nm) and 62 stand on their own water at 0 nm and ARE their own roadstead. Every one of them is on sailable water, every one is exactly snap_nm from its quay so the helper line the chart draws is the distance the table measured, and every one equals what voyage.water_roadstead answers for the same coordinate — the Node generator and the SQL rule are one rule now, because water_snap_nm''s body moved down into it. Collapsing one roadstead onto its quay is FOUND, exactly once. The isthmus: PAN to POR quay-to-quay is still ACCEPTED under the old snap+25 allowance (so the defect was real) and roads-to-roads is refused %, with the table now quoting % nm the long way round. A real house sailed LIS to SET — whose roadstead lies 26.17 nm off her quay, further than the join tolerance, so nothing here would work from the quay — on a roadstead-to-roadstead course; her frozen path BEGAN at the LIS roads, ENDED at the SET roads, and voyage.settle — untouched — docked her at SET itself: the owner''s sentence, proven. The land guard walks her, GRANDFATHERS a pre-0076 isthmus voyage a player would already have bought, and refuses the same course dated after this file. Every place still reaches every other symmetrically and never under the great circle between their roadsteads; the Arctic is shut (LIS->NAG % nm), there is no Suez and no Panama; 13 raster control cells read back through get_bit; 0 client write grants, 0 client-executable writers.',
    v_ports, v_isthmus, (select (reaches->>'POR')::numeric from public.sea_reaches where code = 'PAN'),
    (select (reaches->>'NAG')::numeric from public.sea_reaches where code = 'LIS');
end $$;
